import {translateTree,observeTranslations,localizedPath,t} from './i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url){const r=await fetch(url);const v=await r.json();if(!r.ok)throw Error(v.error);return v;}
export async function mountCatalog(root,actions={}){const host=root.querySelector('[data-vehicle-catalog]');if(!host)return;if(!document.querySelector('[data-studio-css]')){const l=document.createElement('link');l.href='/studio/designer.css';l.rel='stylesheet';l.dataset.studioCss='';document.head.append(l);}const [{makes},{templates}]=await Promise.all([api('/api/vehicles'),api('/api/templates')]);let serial=0;host.innerHTML=`<div class="catalog-fields"><label>Make<select data-make>${makes.map(m=>`<option value="${m}" ${m==='Ford'?'selected':''}>${esc(m)}</option>`).join('')}</select></label><label>Year<select data-year>${Array.from({length:32},(_,i)=>2027-i).map(y=>`<option value="${y}" ${y===2025?'selected':''}>${y}</option>`).join('')}</select></label><label>Model<select data-model></select></label><label>Trim<input data-trim placeholder="e.g. XLT, XL, cargo"></label><label>Body / configuration<input data-body placeholder="e.g. roof height, wheelbase, cab"></label></div><p data-model-status class="small" role="status"></p><button class="btn" data-find style="margin-top:18px">Find templates</button><div class="catalog-results" data-results></div>`;const $=s=>host.querySelector(s);observeTranslations(host);
async function models(){const version=++serial;$('[data-model-status]').textContent='Loading models…';$('[data-find]').disabled=true;try{const data=await api('/api/vehicles?make='+encodeURIComponent($('[data-make]').value)+'&year='+$('[data-year]').value);if(version!==serial)return;$('[data-model]').innerHTML=data.models.map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');if($('[data-make]').value==='Ford'&&data.models.some(m=>/f-150/i.test(m)))$('[data-model]').value=data.models.find(m=>/f-150/i.test(m));$('[data-model-status]').textContent=data.verifiedYear?t('Models verified for the selected year.') :t('Model index: confirm the year and body with our team.');$('[data-find]').disabled=false;find();}catch(e){if(version!==serial)return;$('[data-model-status]').textContent=e.message;$('[data-find]').disabled=false;}}
function selection(){return {make:$('[data-make]').value,model:$('[data-model]').value,year:Number($('[data-year]').value),trim:$('[data-trim]').value.trim(),body:$('[data-body]').value.trim()};}
function find(){const s=selection(),rows=templates.filter(i=>i.make===s.make&&i.model.toLowerCase()===s.model.toLowerCase()&&i.year===s.year&&(!s.trim||i.trim.toLowerCase().includes(s.trim.toLowerCase()))&&(!s.body||i.body.toLowerCase().includes(s.body.toLowerCase())));$('[data-results]').innerHTML=rows.length?rows.map(i=>`<article class="catalog-product"><div>${i.hasPreview?`<img src="/api/template-preview?id=${i.id}" alt="${esc(i.make+' '+i.model)}" style="width:100%;max-height:240px;object-fit:contain">`:""}<span class="chip">Verified vector file</span><h3>${esc(i.year+' '+i.make+' '+i.model)}</h3><p>${esc(i.trim+' · '+i.body)}</p></div><div><p>${esc(i.description)}</p><p>${esc(i.fileName)}</p><p><b>${new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(i.price)}</b></p><a class="btn" href="${localizedPath('/satin/shop/products/'+i.ruleId)}">View product</a></div></article>`).join(''):`<div class="catalog-product"><div><h3>${esc(s.year+' '+s.make+' '+(s.model||''))}</h3><p>${esc(s.trim+' '+s.body)}</p></div><div><h3>No matching vector file is published yet.</h3><p>Request this vehicle template. We will confirm the exact body, file availability and price.</p><button class="btn" data-request>Request this template</button></div></div>`;$('[data-request]')?.addEventListener('click',()=>window.satinOpenQuote?.('Vehicle template request','Vehicle: '+s.year+' '+s.make+' '+s.model+';Trim: '+s.trim+';Body: '+s.body));translateTree(host);}
$('[data-make]').onchange=models;$('[data-year]').onchange=models;$('[data-find]').onclick=find;await models();}
export async function mountManagedShop(root){if(!/^\/satin(?:\/(fa|fr|es))?\/shop\/?$/.test(location.pathname))return;const {products}=await api('/api/products');const managed=products.filter(p=>p.path.startsWith('/satin/shop/products/')&&!p.id.startsWith('vehicle-'));if(!managed.length)return;const section=document.createElement('section');section.className='sec';section.innerHTML=`<div class="wrap"><h2>Shop products</h2><div class="grid g3" style="margin-top:20px">${managed.map(p=>`<a class="card" href="${localizedPath(p.path)}"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><span>${p.stock===0?'Out of stock':'View product'}</span></a>`).join('')}</div></div>`;root.querySelector('.page-enter')?.append(section);observeTranslations(section);}
export async function mountManagedProduct(root,id){const [a,b]=await Promise.all([api('/api/products'),api('/api/templates')]);const p=a.products.find(p=>p.id===id),template=b.templates.find(p=>p.ruleId===id);const host=root.querySelector('[data-managed-product]');if(!host)return;if(!p&&!template){host.innerHTML='<h1>Product unavailable</h1>';return;}const name=p?.name||template.make+' '+template.model+' vector',description=p?.description||template?.description||'';const isMaterial=/material/.test((p?.path||'')+(p?.id||''))||/material|film|tool|squeegee|knife|tape|primer|laminate/i.test((p?.category||'')+' '+name);host.innerHTML=`<nav class="crumbs small"><a href="/satin/">Home</a> / <a href="/satin/shop/">Shop</a>${isMaterial?' / <a href="/satin/shop/materials-tools/">Materials &amp; Tools</a>':''}</nav><h1 class="d2">${esc(name)}</h1><p class="lede">${esc(description)}</p><ul class="shop-trust">${[['truck','Ships across Canada from Vaughan, ON'],['store','Free pickup at our shop'],['shield','Genuine manufacturer stock'],['return','Easy returns on unopened items']].map(([i,t])=>`<li>${ICONS[i]}<span>${t}</span></li>`).join('')}</ul><div class="cfg"></div><section class="shop-info"><div class="shop-info-tabs" role="tablist">${SHOP_INFO.map((x,i)=>`<button type="button" role="tab" aria-selected="${i===0}" data-info-tab="${i}">${x[0]}</button>`).join('')}</div>${SHOP_INFO.map((x,i)=>`<div class="shop-info-panel" data-info-panel="${i}" ${i?'hidden':''}>${x[1]}</div>`).join('')}</section>`;host.querySelectorAll('[data-info-tab]').forEach(b=>b.onclick=()=>{host.querySelectorAll('[data-info-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));host.querySelectorAll('[data-info-panel]').forEach(pn=>pn.hidden=pn.dataset.infoPanel!==b.dataset.infoTab);});const {mountPricingForm}=await import('./calculator.mjs');await mountPricingForm(root,{add:item=>globalThis.satinAddToCart?.(item)});translateTree(host);}
const ICONS={truck:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 6h11v10H3zM14 10h4l3 3v3h-7"/><circle cx="7" cy="17.5" r="1.8"/><circle cx="17" cy="17.5" r="1.8"/></svg>',store:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 9l1.5-5h13L20 9M4 9h16v11H4zM9 20v-6h6v6"/></svg>',shield:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/></svg>',return:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 8h11a5 5 0 0 1 0 10H8"/><path d="M8 4L4 8l4 4"/></svg>'};
const SHOP_INFO=[['Shipping','<p><b>Processing:</b> in-stock items ship in 1–2 business days from Vaughan, Ontario. Special orders ship when they arrive from the manufacturer — we confirm the date by email.</p><p><b>Delivery:</b> shipping is calculated at checkout. Free local pickup is available at 50 Viceroy Rd, Unit 22–23, Vaughan. Film rolls ship in protective cores and boxes.</p>'],['Returns & refunds','<p>Unopened, undamaged items in original packaging can be returned within 30 days for a refund to the original payment method (return shipping is paid by the customer). Cut-to-length film, opened rolls, custom-printed items and clearance items are final sale.</p><p>Received something damaged or incorrect? Email <a href="mailto:info@satingraphic.ca">info@satingraphic.ca</a> within 7 days with photos and your order number and we will replace it.</p>'],['Warranty','<p>Films and tools carry the manufacturer\'s warranty (for example 3M and Avery Dennison performance warranties when installed and maintained to their guidelines). Warranty does not cover installation errors, improper storage or normal wear. We help you file manufacturer claims.</p>'],['Help','<p>Not sure which film or tool you need? Call <a href="tel:+19059626222">(905) 962-6222</a> or email <a href="mailto:info@satingraphic.ca">info@satingraphic.ca</a> — our installers use these products every day.</p>']];

export async function mountMaterials(root){const {products}=await api('/api/products');for(const button of root.querySelectorAll('[data-addmat]')){const p=products.find(p=>p.name===button.dataset.addmat);if(!p){button.closest('.card').hidden=true;continue;}const price=button.parentElement.querySelector('.price');if(price)price.remove();const link=document.createElement('a');link.className=button.className;link.href=localizedPath(p.path);link.textContent=p.stock===0?'Out of stock':'View product';button.replaceWith(link);}translateTree(root);}
